int fd = open("data.log", O_WRONLY | O_CREAT, 0644);

// 1. Retrieve existing flags
int flags = fcntl(fd, F_GETFL);

// 2. Add O_SYNC (Synchronous I/O)
flags |= O_SYNC;

// 3. Apply new flags
fcntl(fd, F_SETFL, flags);

// Subsequent writes block until data is committed to disk
write(fd, data_ptr, data_size);

close(fd);
